import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String sessionUser = (String) req.getSession().getAttribute("username");

        if (sessionUser == null) {
            resp.sendError(401, "Not authenticated");
            return;
        }

        // Validate report type against known values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation - basic format check
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        log.info("Report request: user=" + sessionUser + " type=" + reportType +
                 " dept=" + department + " sort=" + sortCol);

        String baseQuery = getBaseQuery(reportType);
        StringBuilder query = new StringBuilder(baseQuery);

        // Build WHERE clause
        query.append(" WHERE r.active = 1");
        if (startDate != null) {
            query.append(" AND r.created_at >= '").append(startDate).append("'");
        }
        if (endDate != null) {
            query.append(" AND r.created_at <= '").append(endDate).append("'");
        }
        if (department != null && !department.isEmpty()) {
            query.append(" AND r.department = '").append(department).append("'");
        }

        // Sort column - allow dynamic ordering
        if (sortCol != null && !sortCol.isEmpty()) {
            query.append(" ORDER BY ").append(sortCol);
        } else {
            query.append(" ORDER BY r.created_at DESC");
        }

        query.append(" LIMIT 500");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) json.append(", ");
                    json.append("\"").append(meta.getColumnLabel(i)).append("\": ");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory") ||
               type.equals("personnel") || type.equals("audit"));
    }

    private String getBaseQuery(String type) {
        switch (type) {
            case "sales": return "SELECT r.id, r.amount, r.customer, r.created_at FROM sales_reports r";
            case "inventory": return "SELECT r.id, r.item, r.quantity, r.created_at FROM inventory_reports r";
            case "personnel": return "SELECT r.id, r.employee, r.department, r.created_at FROM personnel_reports r";
            case "audit": return "SELECT r.id, r.action, r.target, r.created_at FROM audit_reports r";
            default: return "SELECT r.id, r.created_at FROM reports r";
        }
    }
}
